-- Baseline para bases NUEVAS. En bases existentes usar baseline explícito versión 1.
create table acuerdos_compensacion (fecha_creacion timestamp(6) not null, id bigint generated by default as identity, solicitud_id bigint not null, estado varchar(255) not null check ((estado in ('BORRADOR','CONFIRMADO','RECHAZADO'))), terminos text not null, primary key (id));
create table archivo_cargas (tamano_mb float(53) not null, fecha_subida timestamp(6) not null, horario_academico_id bigint not null, id bigint generated by default as identity, formato varchar(255) not null, nombre varchar(255) not null, primary key (id));
create table conductores (fecha_alta timestamp(6) not null, usuario_id bigint not null, primary key (usuario_id));
create table correo_outbox (intentos integer not null, enviado timestamp(6) with time zone, id bigint generated by default as identity, notificacion_id bigint not null unique, siguiente_intento timestamp(6) with time zone not null, asunto varchar(255) not null, contenido_cifrado text not null, destino varchar(255) not null, primary key (id));
create table cursos (hora_fin time(0) not null, hora_inicio time(0) not null, horario_academico_id bigint not null, id bigint generated by default as identity, dia varchar(255) not null, nombre varchar(255) not null, primary key (id));
create table horario_academicos (fecha_actualizacion timestamp(6), id bigint generated by default as identity, usuario_id bigint not null unique, primary key (id));
create table metodos_compensacion (activo boolean not null, id bigint generated by default as identity, usuario_id bigint not null, descripcion varchar(255) not null, tipo varchar(255) not null check ((tipo in ('DINERO','GASOLINA','FAVOR'))), primary key (id));
create table notificaciones (leida boolean not null, fecha_envio timestamp(6) not null, id bigint generated by default as identity, usuario_id bigint not null, mensaje text not null, tipo varchar(255) not null check ((tipo in ('EXITO','ERROR','ADVERTENCIA','RECORDATORIO'))), primary key (id));
create table pasajeros (fecha_alta timestamp(6) not null, usuario_id bigint not null, primary key (usuario_id));
create table penalidades (fecha timestamp(6) not null, id bigint generated by default as identity, usuario_id bigint not null, viaje_id bigint, motivo varchar(255) not null, tipo varchar(255) not null check ((tipo in ('LEVE','GRAVE'))), primary key (id));
create table perfiles (fecha_fin_clases date not null, fecha_inicio_clases date not null, fecha_actualizacion timestamp(6), id bigint generated by default as identity, usuario_id bigint not null unique, apellidos varchar(255) not null, carrera varchar(255) not null, datos_curiosos text, dias_disponibles varchar(255) not null, distrito varchar(255) not null, gustos text, hobbies text, horarios_disponibles varchar(255) not null, metodo_compensacion_favorito varchar(255) check ((metodo_compensacion_favorito in ('DINERO','GASOLINA','FAVOR'))), nombre varchar(255) not null, universidad varchar(255) not null, primary key (id));
create table rutas (capacidad_maxima integer not null, conductor_id bigint not null, fecha_creacion timestamp(6) not null, id bigint generated by default as identity, destino varchar(255) not null, estado varchar(255) not null check ((estado in ('ACTIVA','LLENA','VENCIDA','ELIMINADA'))), nota_contribucion varchar(255), origen varchar(255) not null, puntos_referencia text not null, zonas_sin_parada text, primary key (id));
create table solicitudes (fecha_creacion timestamp(6) not null, id bigint generated by default as identity, metodo_compensacion_id bigint, pasajero_id bigint not null, viaje_id bigint not null, estado varchar(255) not null check ((estado in ('PENDIENTE','ACEPTADA','RECHAZADA','CANCELADA'))), mensaje text, motivo_rechazo varchar(255), preferencia_compensacion varchar(255) not null check ((preferencia_compensacion in ('DINERO','GASOLINA','FAVOR'))), primary key (id));
create table usuarios (acepta_terminos boolean not null, cuenta_verificada boolean not null, intentos_otp integer default 0 not null, codigo_verificacion_expiracion timestamp(6), fecha_registro timestamp(6) not null, id bigint generated by default as identity, otp_bloqueado_hasta timestamp(6), ultimo_envio_otp timestamp(6), apellidos varchar(255) not null, codigo_verificacion varchar(255), contrasena_hash varchar(255) not null, correo_institucional varchar(255) not null unique, nombre varchar(255) not null, rol_principal varchar(255) check ((rol_principal in ('CONDUCTOR','PASAJERO'))), telefono varchar(255) not null unique, primary key (id));
create table vehiculos (asientos integer not null, conductor_id bigint not null, id bigint generated by default as identity, marca varchar(255) not null, modelo varchar(255) not null, placa varchar(255) not null unique, primary key (id));
create table viajes (confirmado boolean not null, fecha date not null, hora time(0) not null, pasajeros integer default 0 not null, recordatorio_enviado boolean default false, cancelado_por_id bigint, fecha_cancelacion timestamp(6), fecha_confirmacion timestamp(6), id bigint generated by default as identity, ruta_id bigint not null, dia varchar(255) not null, estado varchar(255) not null check ((estado in ('PROGRAMADO','EN_PROGRESO','COMPLETADO','CANCELADO','VENCIDO'))), primary key (id));
